const input = $input.first().json;
let url = String(input.website || '').trim();
if (url && url.indexOf('http') !== 0) url = 'https://' + url;
const looksValid = url.indexOf('.') > -1 && url.indexOf(' ') === -1 && url.length < 300;

const state = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (state.day !== today) { state.day = today; state.count = 0; }
const overLimit = state.count >= 40;
if (looksValid && !overLimit) state.count = state.count + 1;

let company = String(input.company || '').trim();
if (!company && looksValid) company = url.replace('https://', '').replace('http://', '').replace('www.', '').split('/')[0];

return [{ json: { website: url, company: company, ok: looksValid && !overLimit, reason: !looksValid ? 'bad-link' : (overLimit ? 'limit' : '') } }];

const g = $('Clean the link and check the daily limit').first().json;
const data = $input.first().json.data || {};
const text = String(data.markdown || '').slice(0, 7000);
return [{ json: { website: g.website, company: g.company, siteText: text, readOk: text.length > 200 } }];

const o = $input.first().json.output || {};
const p = $('Prepare the page text').first().json;
function noDash(s) { return String(s == null ? '' : s).split(' — ').join(', ').split('—').join(', ').split(' – ').join(', ').split('–').join('-'); }
function esc(s) { return noDash(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); }
function para(s) { return esc(s).split(String.fromCharCode(10)).join('<br>'); }
const signals = (o.signals || []).map(function (s) { return '<li>' + esc(s) + '</li>'; }).join('');
const html = '<div style="text-align:left;max-width:640px;margin:0 auto;font-family:system-ui,sans-serif;line-height:1.5">'
  + '<p style="color:#666;font-size:13px">Read live from ' + esc(p.website) + '</p>'
  + '<h2 style="margin:4px 0">' + esc(p.company) + '</h2>'
  + '<p><b>Fit for the product:</b> ' + esc(o.fitScore) + '/10. ' + esc(o.fitReason) + '</p>'
  + '<h3>The brief</h3>'
  + '<p><b>What they are:</b> ' + esc(o.companySummary) + '</p>'
  + '<p><b>What they sell:</b> ' + esc(o.whatTheySell) + '</p>'
  + '<p><b>Who they serve:</b> ' + esc(o.customerType) + '</p>'
  + '<p><b>Signals:</b></p><ul>' + signals + '</ul>'
  + '<h3>The first email it drafted</h3>'
  + '<div style="border:1px solid #ddd;border-radius:8px;padding:14px;background:#fafafa">'
  + '<p style="margin-top:0"><b>Subject:</b> ' + esc(o.emailSubject) + '</p>'
  + '<p>' + para(o.emailPlain) + '</p></div>'
  + '<p style="color:#666;font-size:13px;margin-top:18px">This is a demo for a fictional company, Corvell Books. No email was sent. Built by DarkLvrd with n8n, Firecrawl and GPT-5 mini. github.com/DarkLvrd/n8n-automation-portfolio</p>'
  + '</div>';
return [{ json: { html: html, company: p.company, website: p.website, fitScore: o.fitScore } }];
